using System.IO; using System.Text.Json; using SaarOSS.Rechnungsprogramm.Models;
namespace SaarOSS.Rechnungsprogramm.Services;
public sealed class CustomerService
{
 private static readonly JsonSerializerOptions Options=new(){WriteIndented=true}; private readonly string _folder=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"SaarOSS","Rechnungsprogramm"); private string FilePath=>Path.Combine(_folder,"customers.json"); private string BackupPath=>Path.Combine(_folder,"customers.backup.json");
 public CustomerStore Load(){if(!File.Exists(FilePath))return new();try{return JsonSerializer.Deserialize<CustomerStore>(File.ReadAllText(FilePath),Options)??new();}catch(Exception ex){throw new InvalidDataException("Die Kundendatei konnte nicht gelesen werden. Die Datei wurde nicht überschrieben.",ex);}}
 public void Save(CustomerStore store){Directory.CreateDirectory(_folder);var temp=FilePath+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(store,Options));if(File.Exists(FilePath))File.Copy(FilePath,BackupPath,true);File.Move(temp,FilePath,true);}
 public Customer SaveCustomer(CustomerStore store,Customer customer){if(customer.SequenceNumber==0){while(store.Customers.Any(x=>x.NumberPrefix.Equals(store.NumberPrefix,StringComparison.OrdinalIgnoreCase)&&x.SequenceNumber==store.NextSequenceNumber))store.NextSequenceNumber++;customer.SequenceNumber=store.NextSequenceNumber++;customer.NumberPrefix=store.NumberPrefix;customer.NumberDigits=store.NumberDigits;}customer.UpdatedAt=DateTimeOffset.Now;var index=store.Customers.FindIndex(x=>x.Id==customer.Id);if(index>=0)store.Customers[index]=customer;else store.Customers.Add(customer);Save(store);return customer;}
 public void SaveNumbering(CustomerStore store,string prefix,int digits,int nextNumber){prefix=prefix.Trim();if(string.IsNullOrWhiteSpace(prefix))throw new ArgumentException("Das Präfix darf nicht leer sein.");if(digits<3||digits>9)throw new ArgumentOutOfRangeException(nameof(digits));if(nextNumber<1||nextNumber>999999999)throw new ArgumentOutOfRangeException(nameof(nextNumber));if(store.Customers.Any(x=>x.NumberPrefix.Equals(prefix,StringComparison.OrdinalIgnoreCase)&&x.SequenceNumber==nextNumber))throw new InvalidOperationException("Diese Kundennummer ist bereits vergeben.");store.NumberPrefix=prefix;store.NumberDigits=digits;store.NextSequenceNumber=nextNumber;store.NumberingMigratedTo211=true;Save(store);}
}
